use novel_storage::{Storage,Scene,SyncCursor};
use serde_json::json;
#[tokio::test]
async fn conflict_resolution_retains_acknowledged_claims_but_cannot_exempt_unacknowledged_ancestor_claims(){
    let a=tempfile::tempdir().unwrap();let b=tempfile::tempdir().unwrap();let s=Storage::open(&a.path().join("planning.sqlite")).await.unwrap();let r=Storage::open(&b.path().join("planning.sqlite")).await.unwrap();let p=s.create_project("Planning resolution").await.unwrap();let c=s.create_chapter(&p.id,"Chapter").await.unwrap();let scene=s.create_scene(&c.id,Scene{schema_version:1,title:"Scene".into(),document:json!({"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مِ 中文 𠀀 👩🏽‍🚀"}]}]})}).await.unwrap();
    let original=json!({"schemaVersion":1,"records":[{"id":"hero","kind":"character","name":"نور 明"}],"facts":[{"id":"fact","subjectId":"hero","property":"Name","value":"مِ 中文 𠀀 👩🏽‍🚀","status":"fact","confirmed":true}],"knowledge":[{"id":"known","characterId":"hero","factId":"fact","stance":"knows","factSnapshot":{"subjectId":"hero","property":"Name","value":"مِ 中文 𠀀 👩🏽‍🚀"},"source":"Ancestor author's source","interpretation":"","scope":{"kind":"scenes","sceneIds":[scene.id]}}]});let base=s.save_project_data(&p.id,"planning",original.clone(),None).await.unwrap();
    let epoch=s.sync_cursor().await.unwrap().epoch;let local=r.sync_cursor().await.unwrap().epoch;let page=s.pull_revisions(&p.id,SyncCursor{epoch:epoch.clone(),sequence:0},100).await.unwrap();r.ingest_revisions(&p.id,&local,&epoch,s.sync_manifest(&p.id).await.unwrap(),page.revisions).await.unwrap();let after=s.sync_cursor().await.unwrap().sequence;
    let mut authored=original.clone();authored["knowledge"][0]["source"]=json!("Local explicitly reauthored source");let changed=s.save_project_data(&p.id,"planning",authored.clone(),Some(base.revision_id.clone())).await.unwrap();let mut withdrawn=authored;withdrawn["facts"][0]["value"]=json!("Changed canon");withdrawn["facts"][0]["confirmed"]=json!(false);withdrawn["facts"][0]["status"]=json!("proposal");let retained=s.save_project_data(&p.id,"planning",withdrawn.clone(),Some(changed.revision_id)).await.unwrap();
    let mut remote=original.clone();remote["knowledge"][0]["source"]=json!("Remote explicitly reauthored source");r.save_project_data(&p.id,"planning",remote,Some(base.revision_id)).await.unwrap();let page=s.pull_revisions(&p.id,SyncCursor{epoch:epoch.clone(),sequence:after},100).await.unwrap();r.ingest_revisions(&p.id,&local,&epoch,s.sync_manifest(&p.id).await.unwrap(),page.revisions).await.unwrap();let heads=r.project_data_heads(&p.id,"planning").await.unwrap().revision_ids;assert_eq!(heads.len(),2);assert!(heads.contains(&retained.revision_id));
    let mut forged=withdrawn.clone();forged["knowledge"][0]=original["knowledge"][0].clone();let marker=r.sync_cursor().await.unwrap();assert!(r.resolve_project_data(&p.id,"planning",forged,heads.clone()).await.is_err());assert_eq!(r.sync_cursor().await.unwrap(),marker);assert_eq!(r.project_data_heads(&p.id,"planning").await.unwrap().revision_ids,heads);
    // Exact retained stale knowledge is recovery, with every parent acknowledged.
    let resolved=r.resolve_project_data(&p.id,"planning",withdrawn.clone(),heads.clone()).await.unwrap();assert_eq!(resolved.payload,withdrawn);assert_eq!(resolved.payload["knowledge"][0]["factSnapshot"],original["knowledge"][0]["factSnapshot"]);let revision=r.load_entity_revision(&p.id,&format!("{}:planning",p.id),"projectData",&resolved.revision_id).await.unwrap();assert_eq!(revision.parents,heads);assert_eq!(r.load_scene(&scene.id).await.unwrap().scene,scene.scene);
}
